-- DEVELOPMENT ONLY. Run via scripts/database.py seed inside its transaction.
-- No admin accounts, passwords, orders, payments, or production seed data.
-- Refuse to reset a database containing customer or administrative data.
DO $$ BEGIN IF EXISTS (SELECT FROM kape.orders) OR EXISTS (SELECT FROM kape.admin_users) THEN RAISE EXCEPTION 'Development seed refused: orders or administrators exist'; END IF; END $$;
